import json
from itertools import product

people = ["G", "H", "K", "L", "P", "S"]
sols = []
for a in product(range(3), repeat=6):
    if any(a.count(d) != 2 for d in range(3)):
        continue
    d = dict(zip(people, a))
    if d["L"] != d["P"]:
        continue
    if d["G"] == d["H"]:
        continue
    if d["K"] == 0 and d["G"] != 1:
        continue
    if d["S"] == 2 and d["H"] != 1:
        continue
    sols.append(d)

opts = {
    "A": lambda d: d["G"] == d["S"],
    "B": lambda d: d["S"] != d["H"],
    "C": lambda d: d["K"] != d["S"],
    "D": lambda d: d["K"] != d["G"],
}
always = [k for k, f in opts.items() if sols and all(f(d) for d in sols)]

if len(always) == 1:
    out = {
        "final_answer": always[0],
        "evidence": {
            "valid_arrangements": len(sols),
            "always_true": always,
            "counts": {k: sum(1 for d in sols if f(d)) for k, f in opts.items()},
        },
    }
    print(json.dumps(out))
else:
    print("UNSUPPORTED")
